"""Draws the logo of Kasauti Capital Partners, the fictional investment firm, in code. Nothing is generated by a model.

It is a river stone in the ash of the firm's kit with one rub of gold across it, which is what a touchstone is for.

uv run python tools/draw_kasauti_logo.py
"""

from pathlib import Path

import yaml
from PIL import Image, ImageDraw

ROOT = Path(__file__).resolve().parent.parent
FOLDER = ROOT / "brands" / "demo-investment-firm"
SIZE, DRAWN_AT = 1024, 2048
# The stone is this wide and this tall, in the middle of the square. The curves are shares of that, each from where the last one ended: two handles and an end.
STONE_WIDTH, STONE_HEIGHT = 1920, 1352
STONE_START = (0.08, 0.42)
STONE_CURVES = (
    ((0.10, 0.14), (0.40, 0.0), (0.62, 0.03)),
    ((0.88, 0.06), (1.02, 0.30), (0.98, 0.58)),
    ((0.95, 0.84), (0.66, 1.0), (0.40, 0.97)),
    ((0.14, 0.94), (0.05, 0.68), (0.08, 0.42)),
)
RUB = ((0.20, 0.66), (0.76, 0.26), (0.82, 0.40), (0.28, 0.78))
CURVE_STEPS = 64


def colours() -> tuple[tuple[int, int, int], tuple[int, int, int]]:
    kit = yaml.safe_load((FOLDER / "kit.md").read_text(encoding="utf-8").split("---")[1])["colors"]
    return tuple(tuple(int(kit[name][at:at + 2], 16) for at in (1, 3, 5)) for name in ("primary", "accent"))


def _on_canvas(point: tuple[float, float]) -> tuple[float, float]:
    return (DRAWN_AT - STONE_WIDTH) / 2 + point[0] * STONE_WIDTH, (DRAWN_AT - STONE_HEIGHT) / 2 + point[1] * STONE_HEIGHT


def _outline() -> list[tuple[float, float]]:
    points, start = [], STONE_START
    for first, second, end in STONE_CURVES:
        for step in range(CURVE_STEPS):
            t = step / CURVE_STEPS
            points.append(tuple((1 - t) ** 3 * start[at] + 3 * (1 - t) ** 2 * t * first[at] + 3 * (1 - t) * t**2 * second[at] + t**3 * end[at] for at in (0, 1)))
        start = end
    return [_on_canvas(point) for point in points]


def draw() -> Image.Image:
    primary, accent = colours()
    # Each colour is drawn on its own clear ground of that same colour, so shrinking the picture leaves no dark fringe round it.
    stone = Image.new("RGBA", (DRAWN_AT, DRAWN_AT), (*primary, 0))
    ImageDraw.Draw(stone).polygon(_outline(), fill=(*primary, 255))
    rub = Image.new("RGBA", (DRAWN_AT, DRAWN_AT), (*accent, 0))
    ImageDraw.Draw(rub).polygon([_on_canvas(point) for point in RUB], fill=(*accent, 255))
    return Image.alpha_composite(stone, rub).resize((SIZE, SIZE), Image.LANCZOS)


def main() -> None:
    out = FOLDER / "logo.png"
    draw().save(out, optimize=True)
    print(f"Wrote {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
